// The expand() vector file in ../test-vectors/expand.json is generated by the
// canopy-screen-runtime (`serializeExpandVectors` over its expand-cases.json)
// and copied here byte for byte; it is the one definition of screen expansion
// shared by the runtime, canopy's screen walk and the probe walker. Never edit
// or reformat it here — regenerate it in the runtime and copy it again.
//
// This test pins two things the consumers rely on: the case shape, and that
// every case document is what this package's validate() says it is (valid
// unless listed in `invalidDocs`; `docsRaw` texts are not documents at all).

import { describe, expect, it } from 'vitest';
import { validate } from './validate.js';

import vectorFile from '../test-vectors/expand.json' with { type: 'json' };

type ExpectNode = {
  screen: string;
  instance: string;
  nodeId: string;
  type: string;
  props: Record<string, unknown>;
  ruleChannels: string[];
  machineBound: boolean;
};

type VectorCase = {
  name: string;
  screenPath: string | null;
  docs: Record<string, unknown>;
  docsRaw: Record<string, string>;
  invalidDocs: string[];
  top: string;
  macros: Record<string, string>;
  expect: { nodes: ExpectNode[]; pvs: string[] };
};

const file = vectorFile as unknown as { mappedTypes: string[]; cases: VectorCase[] };
const cases = file.cases;

const CASE_KEYS = [
  'docs',
  'docsRaw',
  'expect',
  'invalidDocs',
  'macros',
  'name',
  'screenPath',
  'top',
];
const NODE_KEYS = ['instance', 'machineBound', 'nodeId', 'props', 'ruleChannels', 'screen', 'type'];

const isPlainObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

describe('expand vectors (test-vectors/expand.json)', () => {
  it('carries exactly mappedTypes and cases', () => {
    expect(Object.keys(file).sort()).toEqual(['cases', 'mappedTypes']);
    expect(cases.length).toBeGreaterThan(0);
  });

  it('lists mapped types as unique, sorted strings without the structural embed', () => {
    const m = file.mappedTypes;
    expect(Array.isArray(m)).toBe(true);
    expect(m.length).toBeGreaterThan(0);
    for (const t of m) expect(typeof t).toBe('string');
    expect(new Set(m).size).toBe(m.length);
    expect([...m].sort()).toEqual(m);
    expect(m).not.toContain('embedded-display');
    expect(m).toContain('pv-array-plot');
  });

  it('gives every case a unique name', () => {
    const names = cases.map((c) => c.name);
    expect(new Set(names).size).toBe(names.length);
  });

  it.each(cases.map((c) => [c.name, c] as const))('case shape: %s', (_name, c) => {
    expect(Object.keys(c).sort()).toEqual(CASE_KEYS);
    expect(typeof c.name).toBe('string');

    expect(isPlainObject(c.docs)).toBe(true);
    expect(isPlainObject(c.docsRaw)).toBe(true);
    for (const text of Object.values(c.docsRaw)) expect(typeof text).toBe('string');
    for (const key of Object.keys(c.docsRaw)) {
      expect(Object.hasOwn(c.docs, key), `${key} is both a doc and raw text`).toBe(false);
    }

    expect(typeof c.top).toBe('string');
    expect(Object.hasOwn(c.docs, c.top), `top ${c.top}`).toBe(true);
    if (c.screenPath !== null) {
      expect(typeof c.screenPath).toBe('string');
      expect(Object.hasOwn(c.docs, c.screenPath), `screenPath ${c.screenPath}`).toBe(true);
    }

    expect(Array.isArray(c.invalidDocs)).toBe(true);
    for (const key of c.invalidDocs) {
      expect(Object.hasOwn(c.docs, key), `invalidDocs ${key}`).toBe(true);
    }

    expect(isPlainObject(c.macros)).toBe(true);
    for (const v of Object.values(c.macros)) expect(typeof v).toBe('string');

    expect(Object.keys(c.expect).sort()).toEqual(['nodes', 'pvs']);
    expect(Array.isArray(c.expect.pvs)).toBe(true);
    for (const pv of c.expect.pvs) expect(typeof pv).toBe('string');
    expect([...new Set(c.expect.pvs)].sort()).toEqual(c.expect.pvs);

    expect(Array.isArray(c.expect.nodes)).toBe(true);
    expect(c.expect.nodes.length).toBeGreaterThan(0);
    for (const n of c.expect.nodes) {
      expect(Object.keys(n).sort()).toEqual(NODE_KEYS);
      expect(typeof n.screen).toBe('string');
      expect(typeof n.instance).toBe('string');
      expect(typeof n.nodeId).toBe('string');
      expect(typeof n.type).toBe('string');
      expect(isPlainObject(n.props)).toBe(true);
      expect(Array.isArray(n.ruleChannels)).toBe(true);
      for (const ch of n.ruleChannels) expect(typeof ch).toBe('string');
      expect(typeof n.machineBound).toBe('boolean');
      expect(Object.hasOwn(c.docs, n.screen), `node screen ${n.screen}`).toBe(true);
    }
  });

  it('covers both modes, an invalid doc and a raw (non-JSON) doc', () => {
    expect(cases.some((c) => c.screenPath === null)).toBe(true);
    expect(cases.some((c) => c.screenPath !== null)).toBe(true);
    expect(cases.some((c) => c.invalidDocs.length > 0)).toBe(true);
    expect(cases.some((c) => Object.keys(c.docsRaw).length > 0)).toBe(true);
  });

  it.each(cases.map((c) => [c.name, c] as const))(
    'validate(): %s — valid docs pass, invalidDocs fail',
    (_name, c) => {
      for (const [key, doc] of Object.entries(c.docs)) {
        if (c.invalidDocs.includes(key)) {
          expect(validate(doc), key).not.toEqual([]);
        } else {
          expect(validate(doc), key).toEqual([]);
        }
      }
    }
  );
});
